        m["fc_find_follows"] = new[] { "{0} follows its command: {1} → {2} rpm, rising with every step.", "{0} idzie za poleceniem: {1} → {2} obr., rośnie z każdym krokiem.", "{0} folgt dem Befehl: {1} → {2} U/min, steigt mit jedem Schritt.", "{0} suit la commande : {1} → {2} tr/min, en hausse à chaque étape.", "{0} sigue la orden: {1} → {2} rpm, subiendo en cada paso.", "{0} 跟随命令：{1} → {2} rpm，每步上升。", "{0} segue a ordem: {1} → {2} rpm, a subir a cada passo.", "{0} следует команде: {1} → {2} об/мин, растёт с каждым шагом.", "{0} は指令に追従：{1} → {2} rpm、各ステップで上昇。", "{0}은 명령을 따릅니다: {1} → {2} rpm, 단계마다 상승.", "{0} 跟隨命令：{1} → {2} rpm，每步上升。", "{0} komutu izliyor: {1} → {2} rpm, her adımda artıyor.", "{0} bám theo lệnh: {1} → {2} rpm, tăng qua từng bước.", "{0} mengikuti perintah: {1} → {2} rpm, naik di tiap langkah.", "{0} segue il comando: {1} → {2} giri, in salita a ogni passo." };
        m["fc_find_drop"]        = new[] { "{0} read LOWER at {1} than at the step before - it did not follow that increase.", "{0} przy {1} odczytał MNIEJ niż w poprzednim kroku - nie poszedł za tym wzrostem.", "{0} las bei {1} NIEDRIGER als im Schritt davor - er folgte dieser Erhöhung nicht.", "{0} a lu PLUS BAS à {1} qu'à l'étape précédente - il n'a pas suivi cette hausse.", "{0} leyó MENOS en {1} que en el paso anterior - no siguió ese aumento.", "{0} 在 {1} 的读数低于上一步 - 未跟随该次增加。", "{0} leu MENOS a {1} do que no passo anterior - não seguiu esse aumento.", "{0} при {1} прочитан НИЖЕ, чем на предыдущем шаге - не последовал за повышением.", "{0} は {1} で前のステップより低く読み取られました - その増加に追従していません。", "{0}은 {1}에서 이전 단계보다 낮게 읽혔습니다 - 그 증가를 따르지 않았습니다.", "{0} 在 {1} 的讀數低於上一步 - 未跟隨該次增加。", "{0} {1}'de bir önceki adımdan DÜŞÜK okudu - o artışı izlemedi.", "{0} ở {1} đọc THẤP hơn bước trước - không theo mức tăng đó.", "{0} terbaca LEBIH RENDAH pada {1} daripada langkah sebelumnya - tidak mengikuti kenaikan itu.", "{0} ha letto PIÙ BASSO a {1} che al passo precedente - non ha seguito quell'aumento." };
        m["fc_find_floor"]  = new[] { "{0}: even at the lowest step it spun {1} rpm - the laptop itself does not let this fan go slower than that.", "{0}: nawet przy najniższym kroku kręcił {1} obr. - laptop sam nie pozwala temu wentylatorowi zwolnić bardziej.", "{0}: schon beim niedrigsten Schritt {1} U/min - der Laptop selbst lässt diesen Lüfter nicht langsamer laufen.", "{0} : même à l'étape la plus basse il tournait à {1} tr/min - le portable lui-même ne le laisse pas ralentir davantage.", "{0}: incluso en el paso más bajo giraba a {1} rpm - el propio portátil no deja que este ventilador vaya más lento.", "{0}：即使最低档也转 {1} rpm - 笔记本本身不允许该风扇再慢了。", "{0}: mesmo no passo mais baixo rodava a {1} rpm - o próprio portátil não deixa esta ventoinha ir mais devagar.", "{0}: даже на самом низком шаге крутился {1} об/мин - сам ноутбук не даёт этому вентилятору замедлиться сильнее.", "{0}：最低ステップでも {1} rpm - ノートPC 自体がこれ以上遅くさせません。", "{0}: 가장 낮은 단계에서도 {1} rpm - 노트북 스스로 이 팬을 더 느리게 두지 않습니다.", "{0}：即使最低檔也轉 {1} rpm - 筆電本身不允許該風扇再慢了。", "{0}: en düşük adımda bile {1} rpm döndü - dizüstünün kendisi bu fanı daha yavaş çalıştırmıyor.", "{0}: ngay ở bước thấp nhất vẫn quay {1} rpm - bản thân laptop không cho quạt này chậm hơn.", "{0}: bahkan pada langkah terendah berputar {1} rpm - laptop sendiri tidak membiarkan kipas ini lebih lambat.", "{0}: anche al passo più basso girava a {1} giri - il portatile stesso non lascia rallentare di più questa ventola." };
        m["fc_find_gap"]    = new[] { "At {0} % the two fans are far apart ({1} vs {2} rpm). Different fans differ, but a large gap is worth watching - it can be an obstruction or wear on one side.", "Przy {0} % oba wentylatory są daleko od siebie ({1} vs {2} obr.). Różne wentylatory się różnią, ale duża rozbieżność jest warta obserwacji - może to być przeszkoda albo zużycie po jednej stronie.", "Bei {0} % liegen die beiden Lüfter weit auseinander ({1} vs. {2} U/min). Verschiedene Lüfter unterscheiden sich, aber eine große Lücke ist beobachtenswert - eine Blockade oder Verschleiß auf einer Seite ist möglich.", "À {0} % les deux ventilateurs sont très éloignés ({1} vs {2} tr/min). Des ventilateurs différents diffèrent, mais un grand écart mérite attention - obstruction ou usure d'un côté possible.", "Al {0} % los dos ventiladores están muy separados ({1} vs {2} rpm). Ventiladores distintos difieren, pero una gran diferencia merece vigilancia - puede ser una obstrucción o desgaste en un lado.", "在 {0}% 时两个风扇相差很大（{1} vs {2} rpm）。不同风扇本就不同，但差距过大值得留意 - 可能是一侧堵塞或磨损。", "A {0} % as duas ventoinhas estão muito afastadas ({1} vs {2} rpm). Ventoinhas diferentes diferem, mas uma grande diferença merece atenção - pode ser uma obstrução ou desgaste de um lado.", "При {0} % оба вентилятора далеко друг от друга ({1} и {2} об/мин). Разные вентиляторы различаются, но большой разрыв стоит понаблюдать - возможна помеха или износ с одной стороны.", "{0} % で2つのファンが大きく離れています（{1} vs {2} rpm）。ファンが違えば差は出ますが、大きな差は要注意 - 片側の詰まりや摩耗の可能性があります。", "{0} %에서 두 팬이 크게 벌어집니다({1} vs {2} rpm). 팬이 다르면 차이가 나지만 큰 격차는 지켜볼 만합니다 - 한쪽의 막힘이나 마모일 수 있습니다.", "在 {0}% 時兩個風扇相差很大（{1} vs {2} rpm）。不同風扇本就不同，但差距過大值得留意 - 可能是一側阻塞或磨損。", "%{0}'de iki fan birbirinden uzak ({1} vs {2} rpm). Farklı fanlar farklıdır ama büyük fark izlemeye değer - bir tarafta tıkanma veya aşınma olabilir.", "Ở {0} % hai quạt cách xa nhau ({1} so với {2} rpm). Quạt khác nhau thì khác, nhưng chênh lệch lớn đáng theo dõi - có thể là vật cản hoặc mòn một 